# area: context_managers
# hypothesis: An __exit__ annotated to return bool makes checkers treat the with block as possibly swallowing exceptions, so the code after it stays reachable; at runtime the ValueError is indeed swallowed.
from types import TracebackType
from typing import reveal_type


class Swallow:
    def __enter__(self) -> int:
        return 1

    def __exit__(self, exc_type: type[BaseException] | None, exc: BaseException | None, tb: TracebackType | None) -> bool:
        return True


class Propagate:
    def __enter__(self) -> int:
        return 2

    def __exit__(self, exc_type: type[BaseException] | None, exc: BaseException | None, tb: TracebackType | None) -> None:
        return None


def run() -> str:
    with Swallow() as v:
        reveal_type(v)
        raise ValueError('boom')
    return 'after swallow'


print(run())
try:
    with Propagate() as w:
        reveal_type(w)
        raise KeyError('k')
except KeyError as exc:
    print('propagated', exc)
